בעת הפגישה עם הפסיכיאטר, כדאי להגיע מוכנים עם מידע על ההיסטוריה הרפואית שלך וכל טיפול שקיבלת בעבר.","refusal":null,"annotations":[]},"logprobs":null,"finish_reason":"stop"}],"usage":{"prompt_tokens":121,"completion_tokens":176,"total_tokens":297,"prompt_tokens_details":{"cached_tokens":0,"audio_tokens":0},"completion_tokens_details":{"reasoning_tokens":0,"audio_tokens":0,"accepted_prediction_tokens":0,"rejected_prediction_tokens":0}},"service_tier":"default","system_fingerprint":"fp_e3057867b6"}

{"id":"chatcmpl-ELqYS9HoVQOfnywJU3FSf6H5UF7Fq","object":"chat.completion","created":1788875616,"model":"gpt-4o-2024-08-06","choices":[{"index":0,"message":{"role":"assistant","content":"קצבת שירותים מיוחדים נועדה לסייע לאנשים עם מוגבלויות בתפקוד היום-יומי. הזכאות לקצבה זו אינה תלויה רק במגבלה נפשית, אלא נבחנת על סמך יכולתו של האדם לבצע פעולות יום-יומיות בכוחות עצמו, כמו התלבשות, רחצה, אכילה וניידות, ועל סמך הצורך שלו בהשגחה.

